  it('denies websocket upgrades before routing and rejects unknown endpoints',async()=>{const s=await boot();const socket={write:vi.fn(),destroy:vi.fn()};h.http.emit('upgrade',{url:'/ws',allowed:false},socket,Buffer.alloc(0));expect(socket.write).toHaveBeenCalledWith(expect.stringContaining('403'));expect(socket.destroy).toHaveBeenCalledOnce();h.http.emit('upgrade',{url:'/unknown',allowed:true},socket,Buffer.alloc(0));expect(socket.destroy).toHaveBeenCalledTimes(2);h.http.emit('upgrade',{url:'/ws',allowed:true},socket,Buffer.alloc(0));expect(s.addClient).toHaveBeenCalledWith({synthetic:true});h.http.emit('upgrade',{url:'/ws/term?agent=ada',allowed:true},socket,Buffer.alloc(0));expect(s.attachTerminal).toHaveBeenCalledWith('ada',{synthetic:true});});
  it('closes each service once and denies late upgrades on shutdown',async()=>{await boot();h.signals.SIGTERM();await vi.waitFor(()=>expect(process.exit).toHaveBeenCalledWith(0));expect(h.services.swarm.shutdown).toHaveBeenCalledWith(false);expect(h.services.capabilities.close).toHaveBeenCalledOnce();h.signals.SIGINT();await Promise.resolve();expect(h.services.swarm.shutdown).toHaveBeenCalledOnce();const socket={write:vi.fn(),destroy:vi.fn()};h.http.emit('upgrade',{url:'/ws',allowed:true},socket,Buffer.alloc(0));expect(socket.destroy).toHaveBeenCalledOnce();});
